		}
		leader = b
	}
	assuranceMultiEmit(assuranceMultiEvent{
		"event":          "assurance.recovsnap.start",
		"leader":         leader.name,
		"configured_ids": assuranceMultiSortedIDs(configuration),
	})

	// Give A a command to apply, then restart it with the flag on.
	if err := leader.raft.Apply([]byte("before-restart"), 2*time.Second).Error(); err != nil {
		t.Fatalf("pre-restart apply failed: %v", err)
	}
	if !assuranceMultiWaitFSMCommand(a, 3*time.Second) {
		t.Fatalf("A's FSM applied no command before the restart")
	}
	if err := a.raft.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown A failed: %v", err)
	}
	_, trans1 := NewInmemTransport(a.addr)
	trans1.Connect(b.addr, b.trans)
	trans1.Connect(c.addr, c.trans)
	b.trans.Connect(a.addr, trans1)
	c.trans.Connect(a.addr, trans1)
	a.trans = trans1

	confA := *a.conf
	confA.RestoreCommittedLogs = true
	fsmA := &MockFSM{}
	restarted, err := NewRaft(&confA, fsmA, a.logs, a.stable, a.snaps, trans1)
	if err != nil {
		t.Fatalf("flag-on restart of A failed: %v", err)
	}
	a.raft = restarted
	a.fsm = fsmA
	defer func() { _ = restarted.Shutdown().Error() }()

	staged, _ := a.logs.GetCommitIndex()
	aLast := assuranceMultiLastIndex(a)
	logConfigIndex, logConfigVoters, logConfigIDs := assuranceMultiLogConfig(a.logs, aLast)
	confs := assuranceMultiConfigurations(restarted)
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                   "assurance.recovsnap.flag_on_restart",
		"node":                    "A",
		"restore_committed_logs":  true,
		"snapshot_index":          0,
		"staged_commit_index":     staged,
		"a_log_last_index":        aLast,
		"log_config_index":        logConfigIndex,
		"log_config_voters":       logConfigVoters,
		"log_config_ids":          logConfigIDs,
		"latest_config_index":     confs.latestIndex,
		"latest_config_voters":    assuranceMultiVoters(confs.latest),
		"latest_config_ids":       assuranceMultiSortedIDs(confs.latest),
		"committed_config_index":  confs.committedIndex,
		"committed_config_voters": assuranceMultiVoters(confs.committed),
	})

	// Commit one more command and wait until A's FSM has applied it: runFSM refuses a
	// snapshot request while its own last applied index is zero, and the replayed range may
	// contain only configuration and no-op entries for a plain FSM.
	if err := leader.raft.Apply([]byte("after-restart"), 2*time.Second).Error(); err != nil {
		t.Fatalf("post-restart apply failed: %v", err)
	}
	if !assuranceMultiWaitFSMCommand(a, 3*time.Second) {
		t.Fatalf("A's FSM applied no command after the restart")
	}

	// A takes a snapshot through the normal path and the harness reads its metadata.
	if err := restarted.Snapshot().Error(); err != nil {
		t.Fatalf("snapshot on A failed: %v", err)
	}
	snaps, err := a.snaps.List()
	if err != nil || len(snaps) == 0 {
		t.Fatalf("no snapshot metadata on A: %v", err)
	}
	meta := snaps[0]
	snapVoters := assuranceMultiVoters(meta.Configuration)
	snapIDs := assuranceMultiSortedIDs(meta.Configuration)
	snapshotMatchesLogConfig := meta.ConfigurationIndex == logConfigIndex &&
		snapVoters == logConfigVoters && snapIDs == logConfigIDs
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                              "assurance.recovsnap.snapshot",
		"node":                               "A",
		"restore_committed_logs":             true,
		"snapshot_index":                     meta.Index,
		"snapshot_config_index":              meta.ConfigurationIndex,
		"snapshot_config_voters":             snapVoters,
		"snapshot_config_ids":                snapIDs,
		"log_config_index":                   logConfigIndex,
		"log_config_voters":                  logConfigVoters,
		"log_config_ids":                     logConfigIDs,
		"snapshot_config_matches_log_config": snapshotMatchesLogConfig,
	})

	// Restart A again, this time with the replay disabled: the configuration now comes from
	// the snapshot the node itself wrote.
	if err := restarted.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown of restarted A failed: %v", err)
	}
	_, trans2 := NewInmemTransport(a.addr)
	trans2.Connect(b.addr, b.trans)
	trans2.Connect(c.addr, c.trans)
	b.trans.Connect(a.addr, trans2)
	c.trans.Connect(a.addr, trans2)
	a.trans = trans2

	confA2 := *a.conf
	confA2.RestoreCommittedLogs = false
	fsmA2 := &MockFSM{}
	restarted2, err := NewRaft(&confA2, fsmA2, a.logs, a.stable, a.snaps, trans2)
	if err != nil {
		t.Fatalf("flag-off restart of A failed: %v", err)
	}
	a.raft = restarted2
	a.fsm = fsmA2
	defer func() { _ = restarted2.Shutdown().Error() }()

	confs2 := assuranceMultiConfigurations(restarted2)
	leaderObserved := assuranceMultiWaitNode(restarted2, 1500*time.Millisecond)
	snapIndex2, _ := restarted2.getLastSnapshot()
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                               "assurance.recovsnap.flag_off_restart",
		"node":                                "A",
		"restore_committed_logs":              false,
		"restored_snapshot_index":             snapIndex2,
		"latest_config_index":                 confs2.latestIndex,
		"latest_config_voters":                assuranceMultiVoters(confs2.latest),
		"latest_config_ids":                   assuranceMultiSortedIDs(confs2.latest),
		"committed_config_index":              confs2.committedIndex,
		"log_config_index":                    logConfigIndex,
		"log_config_voters":                   logConfigVoters,
		"log_config_ids":                      logConfigIDs,
		"leader_observed":                     leaderObserved,
		"final_state":                         restarted2.State().String(),
		"empty_config_after_flag_off_restart": assuranceMultiVoters(confs2.latest) == 0,
	})

	_ = restarted2.Shutdown().Error()
}

// TestAssuranceReplayBlockedMemberAvailability
//
// Sourced question: what does a member that cannot start cost the cluster? A node whose
// startup replay exceeds the FSM channel's capacity never returns from NewRaft, so it
// never participates, and the group runs with one member fewer. This harness builds a
// three-voter cluster whose committed log is far above any snapshot, restarts one member
// with and without the replay, and then stops one more member: with the replay (which
// blocks) the surviving pair cannot commit, without it the surviving pair still can.
func assuranceRunAvailabilityCase(t *testing.T, caseName string, restoreCommittedLogs bool, commands int, maxAppendEntries int) {
	t.Helper()

	a := assuranceMultiNewNode(t, "A")
	b := assuranceMultiNewNode(t, "B")
	c := assuranceMultiNewNode(t, "C")
	nodes := []*assuranceMultiNode{a, b, c}
	configuration := assuranceMultiConfig(nodes)
	for _, n := range nodes {
		n.conf.MaxAppendEntries = maxAppendEntries
		// Keep the whole committed log above the snapshot so the restart has a large replay.
		n.conf.SnapshotThreshold = 1 << 30
		n.conf.SnapshotInterval = time.Hour
	}

	assuranceMultiWire(nodes)
	for _, n := range nodes {
		if err := BootstrapCluster(n.conf, n.logs, n.stable, n.snaps, n.trans, configuration); err != nil {
			t.Fatalf("bootstrap %s failed: %v", n.name, err)
		}
		r, err := NewRaft(n.conf, n.fsm, n.logs, n.stable, n.snaps, n.trans)
		if err != nil {
			t.Fatalf("NewRaft %s failed: %v", n.name, err)
		}
		n.raft = r
	}
	leader := assuranceMultiLeader(nodes, 5*time.Second)
	if leader == nil {
		t.Fatalf("no leader was elected")
	}
	for _, n := range nodes {
		if n != leader {
			defer func(r *Raft) { _ = r.Shutdown().Error() }(n.raft)
		}
	}
	defer func(r *Raft) { _ = r.Shutdown().Error() }(leader.raft)

	if leader == a {
		target := b
		if err := a.raft.LeadershipTransferToServer(target.id, target.addr).Error(); err != nil {
			t.Fatalf("leadership transfer away from A failed: %v", err)
		}
		if !assuranceMultiWaitNode(target.raft, 5*time.Second) {
			t.Fatalf("transfer target did not become leader")
		}
		leader = target
	}

	for i := 0; i < commands; i++ {
		if err := leader.raft.Apply([]byte("filler"), 5*time.Second).Error(); err != nil {
			t.Fatalf("filler apply %d failed: %v", i, err)
		}
	}
	staged, _ := a.logs.GetCommitIndex()
	aLast := assuranceMultiLastIndex(a)
	snapA, _ := a.raft.getLastSnapshot()
	a.fsm = &MockFSM{}
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                 "assurance.availability.prefix",
		"case":                  caseName,
		"leader":                leader.name,
		"commands":              commands,
		"max_append_entries":    maxAppendEntries,
		"a_staged_commit_index": staged,
		"a_log_last_index":      aLast,
		"a_snapshot_index":      snapA,
		"replay_batches":        (staged - snapA + uint64(maxAppendEntries) - 1) / uint64(maxAppendEntries),
	})

	// Restart A over its own stores with the case's replay setting.
	if err := a.raft.Shutdown().Error(); err != nil {
		t.Fatalf("shutdown A failed: %v", err)
	}
	_, newTrans := NewInmemTransport(a.addr)
	newTrans.Connect(b.addr, b.trans)
	newTrans.Connect(c.addr, c.trans)
	b.trans.Connect(a.addr, newTrans)
	c.trans.Connect(a.addr, newTrans)
	a.trans = newTrans

	confA := *a.conf
	confA.RestoreCommittedLogs = restoreCommittedLogs
	type restartResult struct {
		raft     *Raft
		err      error
		returned bool
		elapsed  int64
	}
	ch := make(chan restartResult, 1)
	go func() {
		start := time.Now()
		r, err := NewRaft(&confA, a.fsm, a.logs, a.stable, a.snaps, newTrans)
		ch <- restartResult{raft: r, err: err, returned: true, elapsed: time.Since(start).Milliseconds()}
	}()
	const waitMS = 8000
	var res restartResult
	select {
	case res = <-ch:
	case <-time.After(waitMS * time.Millisecond):
	}
	excerpt, mentions := "", 0
	if !res.returned {
		buf := make([]byte, 1<<20)
		n := runtime.Stack(buf, true)
		excerpt, mentions = assuranceMultiStackExcerpt(string(buf[:n]), "restoreFromCommittedLogs")
	}
	assuranceMultiEmit(assuranceMultiEvent{
		"event":                  "assurance.availability.restart." + caseName,
		"case":                   caseName,
		"node":                   "A",
		"restore_committed_logs": restoreCommittedLogs,
		"max_append_entries":     maxAppendEntries,
		"replay_entries":         staged,
		"new_raft_returned":      res.returned,
		"elapsed_ms":             res.elapsed,
		"wait_ms":                waitMS,
		"stack_mentions":         mentions,
	})
	if res.returned && res.raft != nil {
		defer func() { _ = res.raft.Shutdown().Error() }()
	}

	// With two members live the group should still commit.
	commitWhileTwoLive := leader.raft.Apply([]byte("while-two-live"), 3*time.Second).Error()

	// Stop the member that is neither the leader nor A: the surviving pair is {leader, A}
	// when A is running, and {leader} when A never started.
	stopped := b
	if leader == b {
		stopped = c
	}
	if stopped == a {
		t.Fatalf("refusing to stop the restarted node")
	}
	stopErr := stopped.raft.Shutdown().Error()
	commitAfterStop := leader.raft.Apply([]byte("after-stop"), 3*time.Second).Error()

	outcome := assuranceMultiEvent{
		"event":                    "assurance.availability.outcome." + caseName,
		"case":                     caseName,
		"node":                     "A",
		"restore_committed_logs":   restoreCommittedLogs,
		"a_new_raft_returned":      res.returned,
		"stopped_node":             stopped.name,
		"stop_error":               fmt.Sprint(stopErr),
		"commit_while_two_live_ok": commitWhileTwoLive == nil,
		"commit_after_stop_ok":     commitAfterStop == nil,
		"commit_after_stop_error":  fmt.Sprint(commitAfterStop),
		"stack_mentions_on_block":  mentions,
		"blocked_stack_excerpt":    excerpt,
	}
	assuranceMultiEmit(outcome)
	if res.returned && res.raft != nil {
		_ = res.raft.Shutdown().Error()
	}
}

func TestAssuranceReplayBlockedMemberAvailability(t *testing.T) {
	const commands = 3000
	const maxAppendEntries = 16 // bound: 128 * 16 = 2048 replayed entries
	assuranceRunAvailabilityCase(t, "replay_on", true, commands, maxAppendEntries)
	assuranceRunAvailabilityCase(t, "replay_off", false, commands, maxAppendEntries)
}

package raft

import (
	"encoding/json"
	"fmt"
	"runtime"
	"sort"
	"strings"
	"testing"
	"time"
)

// TestAssuranceRestoreCommittedLogsConfigurationRecovery
//
// Sourced question: when Config.RestoreCommittedLogs is enabled, does a node that
// restarts on top of its persisted stores still recover the membership configuration
// that its own log already contains?
//
// api.go starts the startup configuration scan at max(snapshotIndex, lastApplied)+1.
// restoreFromCommittedLogs() sets lastApplied to the commit index read from the log
// store before that scan runs, so every configuration entry at an index <= that
// commit index is skipped even though it is present in the node's log.
//
// The harness builds real (bootstrap -> election -> client applies -> shutdown)
// single-voter prefixes on top of a commit-tracking log store, then restarts the node
// with the same stores and a fresh in-memory FSM, once with RestoreCommittedLogs on and
// once with it off, and reports the operands of the recovery.

type assuranceEvent map[string]interface{}

func assuranceEmit(ev assuranceEvent) {
	b, err := json.Marshal(ev)
	if err != nil {
		fmt.Println(`CA_EVENT {"event":"assurance.marshal_error"}`)
		return
	}
	fmt.Println("CA_EVENT " + string(b))
}

type assuranceStores struct {
	addr   ServerAddress
	local  ServerID
	conf   *Config
	logs   *InmemCommitTrackingStore
	stable *InmemStore
	snaps  *InmemSnapshotStore
}

func assuranceWaitElected(t *testing.T, r *Raft, timeout time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if r.State() == Leader {
			return true
		}
		time.Sleep(5 * time.Millisecond)
	}
	return r.State() == Leader
}

// assuranceBuildPrefix runs the pre-restart life of one node and returns the stores it
// leaves behind. applyAfterSnapshot entries are applied after the optional snapshot, and
// the optional configuration change (AddNonvoter of a peer that never connects) is made
// after that snapshot as well, so the node has a committed configuration entry above its
// newest snapshot.
func assuranceBuildPrefix(t *testing.T, withSnapshot bool, caseName string) *assuranceStores {
	t.Helper()

	addr, trans := NewInmemTransport("")
	local := ServerID("server-" + string(addr))
	conf := inmemConfig(t)
	conf.LocalID = local
	// The prefix must run with the feature enabled, otherwise no commit index is ever
	// staged into the log store and the restart has nothing to read.
	conf.RestoreCommittedLogs = true
	conf.TrailingLogs = 16

	stores := &assuranceStores{
		addr:   addr,
		local:  local,
		conf:   conf,
		logs:   NewInmemCommitTrackingStore(),
		stable: NewInmemStore(),
		snaps:  NewInmemSnapshotStore(),
	}
	configuration := Configuration{Servers: []Server{{
		Suffrage: Voter,
		ID:       local,
		Address:  addr,
	}}}
	if err := BootstrapCluster(conf, stores.logs, stores.stable, stores.snaps, trans, configuration); err != nil {
		t.Fatalf("bootstrap failed: %v", err)
	}

	r, err := NewRaft(conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		t.Fatalf("prefix NewRaft failed: %v", err)
	}
	if !assuranceWaitElected(t, r, 3*time.Second) {
		t.Fatalf("prefix node never became leader")
	}

	for i := 0; i < 4; i++ {
		if err := r.Apply([]byte(fmt.Sprintf("pre-%d", i)), 0).Error(); err != nil {
			t.Fatalf("prefix apply failed: %v", err)
		}
	}

	if withSnapshot {
		if err := r.Snapshot().Error(); err != nil {
			t.Fatalf("prefix snapshot failed: %v", err)
		}
		// A committed configuration entry strictly above the snapshot index.
		f := r.AddNonvoter(ServerID("assurance-peer-2"), ServerAddress("assurance-peer-2-addr"), 0, 2*time.Second)
		if err := f.Error(); err != nil {
			t.Fatalf("prefix AddNonvoter failed: %v", err)
		}
		for i := 0; i < 2; i++ {
			if err := r.Apply([]byte(fmt.Sprintf("post-%d", i)), 0).Error(); err != nil {
				t.Fatalf("prefix post apply failed: %v", err)
			}
		}
	}

	// Record the persisted state before shutdown.
	stagedCommit, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	configs, err := assuranceLogConfigEntries(stores.logs, lastIndex)
	if err != nil {
		t.Fatalf("log scan failed: %v", err)
	}
	snapIndex, snapTerm := r.getLastSnapshot()
	assuranceEmit(assuranceEvent{
		"event":                 "assurance.prefix",
		"case":                  caseName,
		"snapshot_present":      withSnapshot,
		"snapshot_index":        snapIndex,
		"snapshot_term":         snapTerm,
		"log_last_index":        lastIndex,
		"staged_commit_index":   stagedCommit,
		"config_entries":        configs.summary,
		"last_config_index":     configs.lastIndex,
		"last_config_voters":    configs.lastVoters,
		"last_config_nonvoters": configs.lastNonvoters,
		"recording_label_count": 0,
	})

	if err := r.Shutdown().Error(); err != nil {
		t.Fatalf("prefix shutdown failed: %v", err)
	}
	return stores
}

type assuranceConfigScan struct {
	summary       string
	lastIndex     uint64
	lastVoters    int
	lastNonvoters int
	lastIDs       []string
}

func assuranceLogConfigEntries(logs *InmemCommitTrackingStore, lastIndex uint64) (assuranceConfigScan, error) {
	out := assuranceConfigScan{summary: ""}
	for idx := uint64(1); idx <= lastIndex; idx++ {
		var entry Log
		if err := logs.GetLog(idx, &entry); err != nil {
			return out, err
		}
		switch entry.Type {
		case LogConfiguration:
			conf := DecodeConfiguration(entry.Data)
			voters, nonvoters := assuranceSuffrageCounts(conf)
			out.summary += fmt.Sprintf("LogConfiguration@%d(servers=%d,voters=%d)", idx, len(conf.Servers), voters)
			out.lastIndex = idx
			out.lastVoters = voters
			out.lastNonvoters = nonvoters
			out.lastIDs = assuranceSortedIDs(conf)
		case LogAddPeerDeprecated, LogRemovePeerDeprecated:
			out.summary += fmt.Sprintf("DeprecatedPeers@%d", idx)
			out.lastIndex = idx
		}
	}
	return out, nil
}

func assuranceSuffrageCounts(conf Configuration) (voters, nonvoters int) {
	for _, s := range conf.Servers {
		if s.Suffrage == Voter {
			voters++
		} else {
			nonvoters++
		}
	}
	return voters, nonvoters
}

func assuranceConfigIDs(conf Configuration) string {
	out := ""
	for i, s := range conf.Servers {
		if i > 0 {
			out += ","
		}
		out += string(s.ID)
	}
	return out
}

// assuranceSortedIDs returns a comparable, order independent list of server IDs.
func assuranceSortedIDs(conf Configuration) []string {
	out := make([]string, 0, len(conf.Servers))
	for _, s := range conf.Servers {
		out = append(out, string(s.ID))
	}
	sort.Strings(out)
	return out
}

// assuranceConfigurations asks the node's main thread for its current view of the
// tracked configurations, mirroring the pattern used by takeSnapshot.
func assuranceConfigurations(r *Raft) configurations {
	fut := &configurationsFuture{}
	fut.ShutdownCh = r.shutdownCh
	fut.init()
	select {
	case r.configurationsCh <- fut:
	case <-r.shutdownCh:
		return configurations{}
	}
	if err := fut.Error(); err != nil {
		return configurations{}
	}
	return fut.configurations
}

// assuranceRunCase restarts the node on top of the stored prefix and reports what the
// recovered node does with its configuration.
func assuranceRunCase(t *testing.T, caseName string, withSnapshot, restoreCommittedLogs bool) {
	t.Helper()

	stores := assuranceBuildPrefix(t, withSnapshot, caseName)
	stagedCommit, err := stores.logs.GetCommitIndex()
	if err != nil {
		t.Fatalf("GetCommitIndex failed: %v", err)
	}
	lastIndex, err := stores.logs.LastIndex()
	if err != nil {
		t.Fatalf("LastIndex failed: %v", err)
	}
	logConfigs, err := assuranceLogConfigEntries(stores.logs, lastIndex)
	if err != nil {
		t.Fatalf("log scan failed: %v", err)
	}

	// The fresh transport keeps the node's address (and therefore its ID) stable.
	_, trans := NewInmemTransport(stores.addr)
	conf := *stores.conf
	conf.RestoreCommittedLogs = restoreCommittedLogs

	assuranceEmit(assuranceEvent{
		"event":                   "assurance.restart." + caseName,
		"case":                    caseName,
		"restore_committed_logs":  restoreCommittedLogs,
		"snapshot_present":        withSnapshot,
		"log_last_index":          lastIndex,
		"staged_commit_index":     stagedCommit,
		"log_last_config_index":   logConfigs.lastIndex,
		"log_last_config_voters":  logConfigs.lastVoters,
		"log_last_config_servers": logConfigs.lastVoters + logConfigs.lastNonvoters,
	})

	r, err := NewRaft(&conf, &MockFSM{}, stores.logs, stores.stable, stores.snaps, trans)
	if err != nil {
		assuranceEmit(assuranceEvent{
			"event":                  "assurance.outcome." + caseName,
			"case":                   caseName,
			"restore_committed_logs": restoreCommittedLogs,
			"snapshot_present":       withSnapshot,
			"new_raft_error":         err.Error(),
		})
		return
	}

	// Observation window: 1.5s is 30 election/heartbeat timeouts of this in-memory
	// configuration (HeartbeatTimeout = ElectionTimeout = 50ms).
	deadline := time.Now().Add(1500 * time.Millisecond)
	leaderObserved := false
	polls := 0
	for time.Now().Before(deadline) {
		polls++
		if r.State() == Leader {
			leaderObserved = true
			break
		}
		time.Sleep(5 * time.Millisecond)
	}

	snapIndex, _ := r.getLastSnapshot()
	lastApplied := r.AppliedIndex()
	leaderAddr, leaderID := r.LeaderWithID()

	// Ask the main thread for the configuration the node is actually tracking.
	confs := assuranceConfigurations(r)
	latestVoters, latestNonvoters := assuranceSuffrageCounts(confs.latest)
	committedVoters, committedNonvoters := assuranceSuffrageCounts(confs.committed)
	latestIDs := assuranceSortedIDs(confs.latest)
	logIDs := logConfigs.lastIDs
	sameMembership := len(latestIDs) == len(logIDs)
	if sameMembership {
		for i := range latestIDs {
			if latestIDs[i] != logIDs[i] {
				sameMembership = false
				break
			}
		}
	}

	assuranceEmit(assuranceEvent{
		"event":                      "assurance.outcome." + caseName,
		"case":                       caseName,
		"restore_committed_logs":     restoreCommittedLogs,
		"snapshot_present":           withSnapshot,
		"leader_observed":            leaderObserved,
		"final_state":                r.State().String(),
		"polls":                      polls,
		"observation_ms":             1500,
		"leader_id":                  string(leaderID),
		"leader_addr":                string(leaderAddr),
		"latest_config_index":        confs.latestIndex,
		"committed_config_index":     confs.committedIndex,
		"latest_config_voters":       latestVoters,
		"latest_config_nonvoters":    latestNonvoters,
		"latest_config_ids":          assuranceConfigIDs(confs.latest),
		"committed_config_voters":    committedVoters,
		"committed_config_ids":       assuranceConfigIDs(confs.committed),
		"snapshot_index":             snapIndex,
		"last_applied":               lastApplied,
		"commit_index":               r.CommitIndex(),
		"last_index":                 r.LastIndex(),
		"committed_config_nonvoters": committedNonvoters,
	})

	// Does the recovered configuration equal the newest configuration entry in the
	// node's own log? Both operands are reported above; this flag is the comparison.
	matches := logConfigs.lastIndex != 0 &&
		sameMembership &&
		latestVoters == logConfigs.lastVoters &&
		latestNonvoters == logConfigs.lastNonvoters
	assuranceEmit(assuranceEvent{
		"event":                          "assurance.config_recovery." + caseName,
		"case":                           caseName,
		"restore_committed_logs":         restoreCommittedLogs,
		"snapshot_present":               withSnapshot,
		"log_last_config_index":          logConfigs.lastIndex,
		"log_last_config_voters":         logConfigs.lastVoters,
		"log_last_config_nonvoters":      logConfigs.lastNonvoters,
		"log_last_config_ids":            strings.Join(logConfigs.lastIDs, ","),
		"latest_config_index":            confs.latestIndex,
		"latest_config_voters":           latestVoters,
		"latest_config_nonvoters":        latestNonvoters,
		"latest_config_ids":              strings.Join(latestIDs, ","),
		"config_matches_last_log_config": matches,
	})

	_ = r.Shutdown().Error()
}

func TestAssuranceRestoreCommittedLogsConfigurationRecovery(t *testing.T) {
